{"command":"cd /testbed/funnel-validation && python3 - <<'EOF'
import csv
from collections import defaultdict

sess = defaultdict(list)
blank = 0
with open("data/events.csv", newline="", encoding="utf-8") as fh:
    rdr = csv.DictReader(fh)
    for r in rdr:
        if not (r["session_id"] or "").strip() or not (r["step"] or "").strip():
            blank += 1
            continue
        sess[r["session_id"]].append((r["event_ts"], r["step"], r["amount_usd"]))
print("rows with blank session_id/step:", blank)

ts_disorder = 0
amt_mismatch = []
zero_or_neg = []
for sid, evs in sess.items():
    ts = [t for t, s, a in evs]
    if ts != sorted(ts):
        ts_disorder += 1
    d = {s: a for t, s, a in evs}
    if "order_confirmed" in d:
        ps, oc = d.get("payment_submit", ""), d["order_confirmed"]
        if ps != oc:
            amt_mismatch.append((sid, ps, oc))
        try:
            v = float(oc)
            if v <= 0: zero_or_neg.append((sid, oc))
        except ValueError:
            zero_or_neg.append((sid, oc))
print("sessions with out-of-order event_ts:", ts_disorder)
print("payment_submit vs order_confirmed amount mismatches:", len(amt_mismatch))
for m in amt_mismatch[:10]: print("  ", m)
print("order_confirmed amount <=0 or unparseable:", len(zero_or_neg), zero_or_neg[:10])
EOF"}
